SELECT ?point ?uri ?class ?tsid WHERE {
  ?z a brick:Zone .
  ?z rdfs:label ?label .
  ?point brick:hasProperty ?p .
  FILTER(?label IN ("Core_ZN","Perimeter_ZN_2"))
  ?point ref:hasExternalReference ?uri .
  ?point ref:hasTimeseriesId ?tsid .
  OPTIONAL { ?p a ?class . }
}

SELECT ?z ?class ?label WHERE {
  ?z a ?class .
  FILTER(str(?z) CONTAINS "ZN")
  OPTIONAL{?z rdfs:label ?label .}
} LIMIT 50

SELECT DISTINCT ?class WHERE {
  ?z a ?class .
  ?z rdfs:label ?label .
  FILTER(CONTAINS(str(?label), "ZN"))
}

SELECT ?z ?label ?point ?pclass ?uri ?tsid WHERE {
  ?z a brick:HVAC_Zone .
  ?z rdfs:label ?label .
  FILTER(?label IN ("Core_ZN","Perimeter_ZN_2"))
  ?point brick:isPointOf ?z .
  ?point a ?pclass .
  ?point ref:hasExternalReference ?uri .
  OPTIONAL{ ?point ref:hasTimeseriesId ?tsid .}
}

